import{artworkLayout}from'./news-artwork.mjs';
export function layoutEditor({element:E,button:B,key='',value=null,onChange=()=>{}}){let layout=structuredClone(artworkLayout(true,key,value));const box=E('section',undefined,'artwork-layout-editor'),board=E('div',undefined,'artwork-layout-board'),bg=E('img'),toolbar=E('div',undefined,'layout-align-tools'),controls=E('div'),regions={};box.append(E('h3','مواضع النص والصورة ومحاذاة النص'),E('p','اسحب إطار النص أو الصورة فوق الخلفية، أو غيّر الموضع والأبعاد من الحقول. تحفظ الإعدادات لهذا النوع.'),toolbar,board,controls);board.append(bg);bg.alt='خلفية نوع الخبر';bg.draggable=false;
 for(const[align,label]of[['right','يمين'],['center','وسط'],['left','يسار']]){const b=B(label,()=>{layout.align=align;paint();onChange()},'secondary');b.dataset.align=align;toolbar.append(b)}
 const inputs=[];for(const[key,label]of[['text','محتوى النص'],['photo','صورة صاحب الخبر']]){const region=E('div',label,'layout-region layout-'+key);region.tabIndex=0;region.setAttribute('role','group');region.setAttribute('aria-label','موضع '+label);regions[key]=region;board.append(region);const fieldset=E('fieldset');fieldset.append(E('legend',label));for(const[field,title]of[['x','الموضع الأفقي'],['y','الموضع الرأسي'],['width','العرض'],['height','الارتفاع']]){const l=E('label',title),input=E('input');input.type='number';input.min=field==='x'||field==='y'?0:60;input.max=1080;input.step=1;l.append(input);fieldset.append(l);inputs.push([key,field,input]);input.oninput=()=>{let v=Number(input.value);if(!Number.isFinite(v))return;layout[key][field]=Math.round(v);clamp(key);paint();onChange()}}controls.append(fieldset);let drag=null;region.onpointerdown=e=>{if(e.button!==undefined&&e.button!==0)return;drag={x:e.clientX,y:e.clientY,start:{...layout[key]}};region.setPointerCapture?.(e.pointerId);e.preventDefault()};region.onpointermove=e=>{if(!drag)return;const width=board.getBoundingClientRect().width;if(!width)return;layout[key].x=Math.round(drag.start.x+(e.clientX-drag.x)*1080/width);layout[key].y=Math.round(drag.start.y+(e.clientY-drag.y)*1080/width);clamp(key);paint();onChange()};region.onpointerup=region.onpointercancel=()=>{drag=null};region.onkeydown=e=>{const delta={ArrowLeft:[-5,0],ArrowRight:[5,0],ArrowUp:[0,-5],ArrowDown:[0,5]}[e.key];if(!delta)return;e.preventDefault();layout[key].x+=delta[0];layout[key].y+=delta[1];clamp(key);paint();onChange()}}
 function clamp(key){const r=layout[key];r.width=Math.max(60,Math.min(1080,r.width));r.height=Math.max(60,Math.min(1080,r.height));r.x=Math.max(0,Math.min(1080-r.width,r.x));r.y=Math.max(0,Math.min(1080-r.height,r.y))}
 function paint(){for(const key of['text','photo']){const r=layout[key];Object.assign(regions[key].style,{left:r.x/10.8+'%',top:r.y/10.8+'%',width:r.width/10.8+'%',height:r.height/10.8+'%',textAlign:layout.align})}for(const[key,field,input]of inputs)input.value=String(layout[key][field]);for(const b of toolbar.children)b.setAttribute('aria-pressed',String(b.dataset.align===layout.align))}
 const reset=B('استعادة المواضع الافتراضية',()=>{layout=structuredClone(artworkLayout(true,key));paint();onChange()},'text-button');box.append(reset);function updateKey(next){key=next;box.hidden=!key;bg.src=key?'/news-artwork/'+key+'.png':''}updateKey(key);paint();return{element:box,get value(){return structuredClone(layout)},updateKey}
}
